                logging.warning(f"Please choose num_frames divisible by num_temporal_chunk for better performance." f"Current get num_frames={num_frames} and num_temporal_chunk={num_temporal_chunk}.")

    def wrap(self,
             pipe: Union[StableVideoDiffusionPipeline, AnimateDiffPipeline,]
             ) -> None:
        # wrap animatediff
